        if (n > INT64_MAX / src.len || src.len * n > (int64_t)(PTRDIFF_MAX / sizeof(T_Variant)))
            vu_fail(line, "list of %lld x %lld elements is too large", (long long)src.len, (long long)n);
        int64_t total = src.len * n;
        r.data = (T_Variant *)vu_malloc((size_t)total * sizeof(T_Variant));
        r.len = r.cap = total;
        if (src.len == 1) { T_Variant v = src.data[0]; for (int64_t k = 0; k < total; k++) r.data[k] = v; }
